      h+='<div class="event"><div class="event-h"><span class="etype '+(e.type==='show'?'show':e.type==='tv'?'tv':'')+'">'+({show:'Show',tv:'TV',pocket:'Pocket',part:'Participação'}[e.type]||esc(e.type))+'</span><span class="event-name">'+esc(e.name)+'</span></div>';
