  h+='<div class="seg" role="group" aria-label="Filtro"><button type="button" data-act="mine-on" aria-pressed="'+ui.onlyMine+'">Só o meu</button><button type="button" data-act="mine-off" aria-pressed="'+(!ui.onlyMine)+'">Equipe toda</button></div>';
  var steps=d.steps.slice();
