function pendencias(){
  var out=[],k0=todayKey();
  S.days.forEach(function(d){if(dkey(d)<k0)return;
    var lbl=d.dd+'/'+d.mm+' · '+d.city;
    if(!d.hotel&&d.events.length) out.push([d.id,lbl,'Hotel não informado']);
    if(!d.vans.length&&d.events.length) out.push([d.id,lbl,'Sem grade de vans']);
    d.events.forEach(function(e){var f=[];if(!e.venue)f.push('local');if(!e.showtime)f.push('show time');if(!e.soundcheck)f.push('passagem');if(f.length)out.push([d.id,lbl,esc(e.name)+': falta '+f.join(', ')])});
    d.flights.forEach(function(f){var x=[];if(!f.cia)x.push('companhia');if(!f.num&&f.kind!=='jato')x.push('nº do voo');if(!f.arr)x.push('chegada');if(!f.to)x.push('destino');if(x.length)out.push([d.id,lbl,'Voo '+esc(f.from||'')+' → '+esc(f.to||'?')+': falta '+x.join(', ')])});
  });
  var nd=S.people.filter(function(p){return p.team==='nd'});
  if(nd.length) out.push(['@pessoas','Pessoas','Sem setor: '+nd.map(function(p){return esc(p.name)}).join(', ')]);
  return out;
}
