  h+='<div class="card-n">Última publicação com dados: '+(S.updatedAt?esc(fmtAt(S.updatedAt)):'—')+'</div></section>'+qu;
  h+='<section class="ablock"><div class="ablock-h"><h2>Ver o app como</h2><span class="sp"></span></div><div class="fld"><label for="f-viewas">Escolha uma pessoa para conferir o que ela vê</label><div class="pinrow"><select id="f-viewas" style="flex:1;background:var(--case);border:1px solid var(--line);border-radius:8px;padding:9px 10px">'+S.people.map(function(p){return '<option value="'+p.id+'"'+(p.id===ui.me?' selected':'')+'>'+esc(p.name)+' · '+esc(team(p).name)+'</option>'}).join('')+'</select><button class="btn primary" data-act="preview">Abrir</button></div></div></section>';
  h+='<section class="ablock"><div class="ablock-h"><h2>Google Agenda da equipe</h2><span class="sp"></span></div><form class="fld" id="gcalform" autocomplete="off"><label for="f-gcal">E-mail ou ID da agenda que aparece no app (só ADM altera)</label><div class="pinrow"><input id="f-gcal" name="gcal" style="flex:1" value="'+esc((S.tour&&S.tour.gcal)||'')+'" placeholder="agenda@gmail.com"><button type="submit" class="btn">Salvar</button></div></form><div class="card-n">A agenda precisa estar pública no Google para a equipe ver. Deixe vazio para tirar a agenda do app.</div></section>';
  var last=(S.history||[]).slice(0,3);
