    x.dd=('0'+g('dd')).slice(-2);x.mm=('0'+g('mm')).slice(-2);x.city=g('city');x.uf=g('uf');x.dayNotes=splitLines(g('dayNotes'));var cm={resp:g('cresp'),phone:g('cphone'),local:g('cloc'),pedidos:splitLines(g('cped'))};x.camarim=(cm.resp||cm.phone||cm.local||cm.pedidos.length)?cm:null;
    if(!s.id){S.days.push(x);ui.day=x.id}
    S.days.sort(function(a,b){return (+a.mm*100+ +a.dd)-(+b.mm*100+ +b.dd)});S.updatedAt=new Date().toISOString();ui.dirty=true;
