/* ---------- ADM: atualizar o app com texto ou PDF ---------- */
var QU={busy:false,msg:'',plan:null,file:null,text:''};
function quickUpdView(){
  var h='<section class="ablock qu"><div class="ablock-h"><h2>Atualizar o app</h2><span class="sp"></span></div>';
  if(QU.plan){var P=QU.plan;
    h+='<div class="card-n" style="margin-bottom:8px">'+esc(P.summary||'Mudanças encontradas:')+'</div>';
    (P.changes||[]).forEach(function(c,i){h+='<label class="qchg"><input type="checkbox" data-qc="'+i+'"'+(c._off?'':' checked')+'><span>'+esc(quLabel(c))+'</span></label>'});
    if(!(P.changes||[]).length) h+='<div class="card-n">Nada para mudar foi encontrado.</div>';
    h+='<div class="sheet-actions" style="margin-top:10px"><span class="sp"></span><button type="button" class="btn" data-qu="cancel">Descartar</button>'+((P.changes||[]).length?'<button type="button" class="btn primary" data-qu="apply">Aplicar no app</button>':'')+'</div><div class="card-n">Ao aplicar, o app já publica para todos os portais.</div>';
    return h+'</section>';
  }
  h+='<div class="card-n" style="margin-bottom:8px">Cole o texto do grupo ou anexe o PDF do roteiro. O app lê, mostra o que vai mudar e você confirma.</div>';
  h+='<textarea id="qu-text" placeholder="Ex.: Amanhã a van técnica sai 13h do hotel. Hotel em Taubaté: Ibis, check-in 14h.">'+esc(QU.text)+'</textarea>';
  h+='<div class="pinrow" style="margin-top:8px;align-items:center"><label class="btn" style="cursor:pointer">'+(QU.file?esc(QU.file.name.slice(0,28)):'Anexar PDF ou .txt')+'<input type="file" id="qu-file" accept="application/pdf,.pdf,text/plain,.txt" hidden></label><span style="flex:1"></span><button type="button" class="btn primary" data-qu="go"'+(QU.busy?' disabled':'')+'>'+(QU.busy?'Lendo…':'Ler e atualizar')+'</button></div>';
  if(QU.msg) h+='<div class="card-n" style="margin-top:8px">'+esc(QU.msg)+'</div>';
  h+='<div class="sheet-actions" style="margin-top:10px"><span class="card-n" style="flex:1">Juntar horários repetidos que já estão no app (ex.: a mesma saída de ônibus escrita duas vezes).</span><button type="button" class="btn" data-qu="dedupe">Revisar repetidos</button></div>';
  return h+'</section>';
}
function quLabel(c){
  if(c.op==='step'){var f2=quFindStep(c),t=f2&&f2.s,td=f2&&f2.d;if(!t)return 'Item não encontrado (ignorado)';
    var lb=quTeamsLabel(c.teams);return 'Atualizar '+td.dd+'/'+td.mm+' · '+t.time+' '+t.title+': '+(c.time&&c.time!==t.time?'horário '+t.time+' → '+c.time+(c.note?' · ':''):'')+(c.note?(lb?'para '+lb+', ':'')+c.note:'')}
  if(c.op==='notice') return 'Aviso'+(c.level==='urg'?' importante':'')+': '+c.text;
  if(c.op==='day'){var ex=S.days.some(function(d){return d.dd+'/'+d.mm===c.date});var parts=[];
    if(c.steps&&c.steps.length)parts.push(c.steps.length+' horário(s): '+c.steps.slice(0,3).map(function(s){return s.time+' '+s.title}).join(' · ')+(c.steps.length>3?'…':''));
    if(c.hotel&&c.hotel.name)parts.push('hotel '+(c.hotel.for==='artistico'?'do artístico ':c.hotel.for==='ambos'?'(equipe e artístico) ':'da equipe ')+c.hotel.name);if(c.rooming&&c.rooming.rooms&&c.rooming.rooms.length)parts.push(c.rooming.rooms.length+' quarto(s) '+(c.rooming.for==='artistico'?'do artístico':'da equipe'));if(c.show&&(c.show.showtime||c.show.name))parts.push('show '+[c.show.name,c.show.showtime].filter(Boolean).join(' '));if(c.notes&&c.notes.length)parts.push(c.notes.length+' observação(ões)');
    return (ex?'Atualizar ':'Criar dia ')+c.date+(c.city?' · '+c.city:'')+': '+(parts.join(' · ')||'sem detalhes');}
  return JSON.stringify(c).slice(0,120);
}
function loadPdfJs(){return new Promise(function(ok,no){if(window.pdfjsLib)return ok(window.pdfjsLib);var sc=document.createElement('script');sc.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';sc.onload=function(){try{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';ok(window.pdfjsLib)}catch(e){no(e)}};sc.onerror=no;document.head.appendChild(sc)})}
function pdfText(file){return file.arrayBuffer().then(function(buf){return loadPdfJs().then(function(lib){return lib.getDocument({data:buf}).promise}).then(function(doc){var ps=[];for(var i=1;i<=Math.min(doc.numPages,30);i++)ps.push(doc.getPage(i).then(function(pg){return pg.getTextContent().then(function(tc){return tc.items.map(function(x){return x.str+(x.hasEOL?'\n':' ')}).join('')})}));return Promise.all(ps).then(function(a){return a.join('\n\n')})})})}
function quContext(){return S.days.map(function(d){return d.dd+'/'+d.mm+' '+d.city+' ('+d.uf+'): '+d.steps.map(function(s){return '['+s.id+'] '+s.time+' '+s.modal+' '+s.title+(s.note?' ('+String(s.note).slice(0,60)+')':'')}).join('; ')+(d.hotel?' | hotel '+d.hotel.name:'')}).join('\n')}
function quRedact(t){return String(t||'').replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g,'[CPF removido]').replace(/\b(\d{2})\/(\d{2})\/(19\d{2}|200\d|201[0-5])\b/g,'[data removida]').replace(/DATA DE\s*\n?\s*NASCIMENTO/gi,'').replace(/\bCPF\b/g,'')}
function quWeekendCtx(){try{var w=weekend();return w.shows.map(function(d){return d.dd+'/'+d.mm+' '+d.city}).join(', ')}catch(e){return ''}}
function quRun(){
  var ta=document.getElementById('qu-text');QU.text=ta?ta.value:QU.text;
  if(!QU.text.trim()&&!QU.file){QU.msg='Cole um texto ou anexe um arquivo.';render();return}
  QU.busy=true;QU.msg='';render();
  var getText=QU.file?(/pdf$/i.test(QU.file.type)||/\.pdf$/i.test(QU.file.name)?pdfText(QU.file):QU.file.text()):Promise.resolve('');
  getText.then(function(ft){var src=quRedact((QU.text.trim()+'\n\n'+(ft||'')).trim()).slice(0,30000);
    var saveInbox=function(){if(liveDb){var p=person(ui.me);liveDb.collection('inbox').add({at:new Date().toISOString(),by:p.id,byName:p.name,file:QU.file?QU.file.name:'',text:src.slice(0,20000)}).catch(function(){})}};
    return (window.claude&&window.claude.use?window.claude.use('sample'):Promise.resolve(null)).then(function(sample){
      if(!sample){saveInbox();QU.busy=false;QU.msg='O leitor automático não está disponível nesta tela. O material ficou salvo em Recebidos para aplicar depois.';render();return}
      var yr=new Date().getFullYear();
      var prompt='Você atualiza o app de logística da turnê Hugo & Guilherme (ano '+yr+'). Leia o MATERIAL e devolva SÓ JSON no formato {"summary":"1 frase em português","changes":[...]}. Cada change é um destes:\n'+
        '{"op":"notice","text":"aviso curto","level":"urg"|"info"}\n'+
        '{"op":"day","date":"dd/mm","city":"Cidade","uf":"UF","show":{"name":"","venue":"","showtime":"23h45","soundcheck":""} ou null,"steps":[{"time":"14h00","title":"","note":"","modal":"onibus|voo|jato|van|hotel|palco|aeroporto|chegada|livre","teams":["all"] ou lista de "tec","band","prod","cont","om","seg","artc","trip","bus","people":["nomes citados nominalmente para este transporte"] (opcional),"notPeople":["nomes que o material tira deste transporte"] (opcional)}],"hotel":{"for":"equipe"|"artistico"|"ambos","name":"","address":"","phone":"","maps":"link https do mapa","distance":"hotel x evento","checkin":"","checkout":""} ou null,"rooming":{"for":"equipe"|"artistico","rooms":[{"room":"nº do quarto ou vazio","who":"nomes (só apelido/nome, sem CPF)","type":"tipo"}]} ou null,"notes":["observação"],"bags":["informação de malas, bagagens, instrumentos e materiais"]}\n'+
        '{"op":"step","date":"dd/mm","id":"id entre colchetes de um item que JÁ EXISTE","time":"novo horário ou vazio","note":"só a informação nova","teams":["all"] ou lista de setores,"people":[] e "notPeople":[] opcionais como acima}\n'+
        'LEITURA INTERNA (obrigatória): antes de criar qualquer horário, compare com DIAS JÁ NO APP. Se o material fala de algo que já existe (o mesmo ônibus, van, voo, jato, show ou saída, mesmo que escrito de outro jeito, ex.: "bus" = ônibus, ou que só mude o horário), use op "step" com o id desse item e NÃO repita o item em "day". Uma instrução para um setor sobre um item existente (ex.: "ligar o ar do bus na saída às 22h30, enviar para os motoristas") é op "step" no item da saída do ônibus, com note "Ligar o ar do bus na saída" e teams ["bus"]. Só crie horário novo em "day" quando não houver item correspondente.\n'+
        'FONTES OFICIAIS: roteiro do dia = Dandan, Julia e Luizmar; voos, jato, hotel, rooming, ônibus e rota = Dandan e Julia; vans, placas e telefones dos motoristas = Dandan, Julia e Rafael (segurança); bagagens e materiais = Dandan, Julia, Japa e Jeff. Se o MATERIAL mostrar que a informação veio de outra pessoa e ela contradiz o que já está no app num desses assuntos, não mude o item: mande um notice level "info" pedindo confirmação à fonte oficial. Avisos de uniforme não entram no app (ignore).\n'+
        'QUEM VAI EM QUAL TRANSPORTE (leitura de continuidade, vale para todos): Rafa (videomaker) e Cica (fotógrafo), setor Conteúdo, vão sempre na van de Produção, principalmente na saída para o show; o app já faz isso sozinho, não precisa repetir. Quem embarca no jato com os artistas segue com eles no carro do hangar até o evento e não pega van; o app já faz isso também. Quem chega por um transporte segue no transporte ligado a ele (ex.: quem chega no ônibus da banda segue com a banda). O que a produção (Dandan, Julia, Luizmar) escrever nominalmente prevalece: se o material disser que uma pessoa vai em outro carro/van/jato, use "people" naquele transporte e "notPeople" no transporte de onde ela sai (op "step" no item existente).\n'+
        'Hotel: "equipe" = produção, banda e técnica; "artistico" = artistas, assessores, segurança, tripulação e staff. Se o material não disser a data, use a data do show cuja cidade aparece no material; se não houver cidade, use o próximo show. FIM DE SEMANA ATUAL: '+quWeekendCtx()+'. Rooming: só use "room" quando o material trouxer o número real do quarto (números de linha 1, 2, 3 não são quarto). Lista de quartos sem data: use a data do próximo show em que o hotel citado aparece em DIAS JÁ NO APP (ou o próximo show). Só a lista de quartos do artístico/staff sem hotel e sem data é a lista padrão e não vira change. Não repita aviso que já existe em AVISOS JÁ NO APP: se for o mesmo assunto atualizado, mande o texto novo completo que o app substitui.\n'+
        'Regras: use só o que está escrito, nunca invente horário, nome ou lugar; horários no formato 14h00; um change "day" por data, só com os horários que o material traz para aquela data (o app junta com os que já existem); não inclua CPF nem data de nascimento; se nada servir, changes vazio.\n\nDIAS JÁ NO APP:\n'+quContext()+'\n\nAVISOS JÁ NO APP:\n'+(S.notices||[]).slice(0,30).map(function(x){return '- '+String(x.text).slice(0,160)}).join('\n')+'\n\nMATERIAL:\n'+src;
      return sample.json(prompt,{modelTier:'complex'}).then(function(v){
        if(!v||!Array.isArray(v.changes))throw {message:'resposta sem mudanças'};
        v.changes.forEach(function(c){if(c&&c.op==='day'&&!/^\d{1,2}\/\d{1,2}$/.test(String(c.date||''))){var w=weekend().shows,cc=nrm(c.city||''),hit=w.filter(function(d){return cc&&nrm(d.city).indexOf(cc)>=0})[0]||w[0];if(hit){c.date=hit.dd+'/'+hit.mm;c.city=c.city||hit.city}}});
        v.changes=v.changes.filter(function(c){return c&&(c.op==='notice'&&c.text||c.op==='step'&&c.id&&/^\d{1,2}\/\d{1,2}$/.test(String(c.date||''))||c.op==='day'&&/^\d{1,2}\/\d{1,2}$/.test(String(c.date||'')))}).slice(0,40);
        QU.plan=v;QU.plan.src=src;QU.busy=false;saveInbox();render();
      });
    });
  }).catch(function(e){QU.busy=false;QU.msg=e&&e.code==='not_granted'?'Permissão do assistente negada nesta tela.':'Não consegui ler o material'+(e&&e.message?' ('+String(e.message).slice(0,80)+')':'')+'. Tente de novo ou cole o texto.';render()});
}
function quTeamIds(teams){if(!teams||!teams.length||teams.indexOf('all')>=0)return 'all';var ids=S.people.filter(function(p){return teams.indexOf(p.team)>=0}).map(function(p){return p.id});return ids.length?{only:ids}:'all'}
function quMin(t){var m=String(t||'').match(/(\d{1,2})\s*[h:]\s*(\d{2})?/);return m?(+m[1])*60+(+(m[2]||0)):null}
function quNorm(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
/* ---------- leitura interna: reconhece o mesmo item escrito de outro jeito ---------- */
var QSTOP={de:1,do:1,da:1,dos:1,das:1,para:1,pra:1,p:1,o:1,a:1,os:1,as:1,e:1,no:1,na:1,nos:1,nas:1,ao:1,aos:1,com:1,em:1,um:1,uma:1,the:1,h:1};
var QSYN={bus:'onibus',buzao:'onibus',sai:'saida',saem:'saida',saidas:'saida',sair:'saida',partida:'saida',decolagem:'voo',embarque:'voo',show:'show',showtime:'show',vans:'van',hoteis:'hotel',heg:'',hg:''};
function quToks(t){var o={};quNorm(t).split(' ').forEach(function(w){if(!w||QSTOP[w]||/^\d/.test(w))return;w=QSYN[w]!=null?QSYN[w]:w;if(w)o[w]=1});return o}
function quSim(a,b){var A=quToks(a),B=quToks(b),i=0,n=0,k;for(k in A){n++;if(B[k])i++}for(k in B)if(!A[k])n++;return n?i/n:0}
var QSOLO={onibus:1,voo:1,jato:1};
function quSame(x,o){if(quNorm(x.title)===quNorm(o.title))return 3;if(x.modal!==o.modal)return 0;
  var sm=quSim(x.title,o.title);if(x.modal==='palco')return (/show/.test(quNorm(x.title))&&/show/.test(quNorm(o.title)))?2:(sm>=0.6?2:0);
  var kx=quVanKey(x.title).join(),ko=quVanKey(o.title).join();if(x.modal==='van'&&kx&&ko&&kx!==ko)return 0;
  var a=quMin(x.time),b=quMin(o.time),df=(a==null||b==null)?0:Math.min(Math.abs(a-b),1440-Math.abs(a-b));
  if(sm>=0.85||(sm>=0.6&&df<=90))return 2;if(x.time&&x.time===o.time&&QSOLO[x.modal])return 1;return 0}
function quTeamsLabel(teams){if(!teams||!teams.length||teams.indexOf('all')>=0)return '';return teams.map(function(t){return S.teams[t]?S.teams[t].name:t}).join(', ')}
function quAddNote(st,note,teams){note=String(note||'').trim();if(!note)return;var lb=quTeamsLabel(teams),line=(lb&&st.who!=='all'?'':lb?'Para '+lb+': ':'')+note;
  if(quNorm(st.note||'').indexOf(quNorm(note))>=0)return;st.note=st.note?st.note+' · '+line:line}
function quPlace(d,st){var i=d.steps.indexOf(st);if(i>=0)d.steps.splice(i,1);var keys=[],add=0,prev=-1;d.steps.forEach(function(x){var k=quMin(x.time);if(k==null)k=prev<0?0:prev;if(k+add<prev)add+=1440;keys.push(k+add);prev=k+add});
  var m=quMin(st.time),late=keys.some(function(k){return k>=720});if(m!=null&&m<360&&late&&keys.length&&keys[0]>=360)m+=1440;
  var pos=d.steps.length;if(m!=null)for(var j=0;j<keys.length;j++){if(keys[j]>m){pos=j;break}}d.steps.splice(pos,0,st)}
function quDedupe(d){var n=0;for(var i=0;i<d.steps.length;i++)for(var j=i+1;j<d.steps.length;j++){var a=d.steps[i],b=d.steps[j],lv=quSame(a,b);
    if(lv>=1){var keep=(b.updated&&(!a.updated||b.updated.at>a.updated.at))?b:a,drop=keep===a?b:a;
      if(drop.note)quAddNote(keep,drop.note);if(drop.who!==keep.who&&(drop.who==='all'||keep.who==='all'))keep.who='all';
      d.steps.splice(d.steps.indexOf(drop),1);stamp(keep);n++;j=i}}
  return n}
function quDedupeAll(){var n=0;S.days.forEach(function(d){var k=quDedupe(d);if(k){n+=k;logH('Organizou',d.dd+'/'+d.mm+' '+d.city+': '+k+' item(ns) repetido(s) juntado(s)',d.dd+'/'+d.mm)}});return n}
function quVanKey(t){var n=quNorm(t),o=[];['tecnica','producao','banda','cargo'].forEach(function(k){if(n.indexOf(k)>=0)o.push(k)});return o}
function quPropTime(d,st,old){if(!old||old===st.time)return;var ks=quVanKey(st.title);
  if(st.modal==='van')(d.vans||[]).forEach(function(v){if(v.time===old&&(!ks.length||ks.some(function(k){return quNorm(v.name).indexOf(k)>=0}))){v.time=st.time;stamp(v)}});
  if(st.modal==='onibus')(d.buses||[]).forEach(function(b){if(b.dep===old)b.dep=st.time});
  if(st.modal==='voo'||st.modal==='jato')(d.flights||[]).forEach(function(f){if(f.dep===old)f.dep=st.time});
  if(st.modal==='palco'&&/show/.test(quNorm(st.title)))quShowTime(d,st.time)}
function quShowTime(d,t){(d.events||[]).forEach(function(e){if(e.type==='show')e.showtime=t});(d.steps||[]).forEach(function(x){if(x.modal==='palco'&&/show/.test(quNorm(x.title))&&x.time!==t){x.time=t;stamp(x)}});
  var ad=S.artists.days.filter(function(x){return x.dd===d.dd&&x.mm===d.mm})[0];if(ad&&ad.schedule)ad.schedule.forEach(function(x){if(x.main){var end=String(x.time).split('/')[1];x.time=t+(end?' /'+end:'')}})}
function quVanAdd(d,st){if(st.modal!=='van')return;var ks=quVanKey(st.title);if(!ks.length)return;d.vans=d.vans||[];
  ks.forEach(function(k){if(d.vans.some(function(v){return v.time===st.time&&quNorm(v.name).indexOf(k)>=0}))return;var nm={tecnica:'Van Técnica',producao:'Van Produção',banda:'Van Banda',cargo:'Van Cargo'}[k],tm={tecnica:'tec',producao:'prod',banda:'band',cargo:'nd'}[k];
    d.vans.push({id:'v'+Date.now().toString(36)+k.slice(0,2),name:nm,team:tm,time:st.time,people:st.note||st.title})})}
function quFindStep(c){var pr=String(c.date||'').split('/'),dd=('0'+pr[0]).slice(-2),mm=('0'+(pr[1]||'')).slice(-2);var d=S.days.filter(function(x){return x.dd===dd&&x.mm===mm})[0];if(!d)return null;var st=d.steps.filter(function(x){return x.id===String(c.id)})[0];return st?{d:d,s:st}:null}
function quPeopleIds(ns){if(!ns||!ns.length)return [];return ns.map(function(n){var k=quNorm(n);if(!k)return null;var p=S.people.filter(function(p){var a=quNorm(p.name),b=quNorm(p.fullName||'');return a===k||b===k||a.split(' ')[0]===k||b.indexOf(k)===0})[0];return p&&p.id}).filter(Boolean)}
function quPeopleApply(st,c){var ids=quPeopleIds(c.people);if(!ids.length)return;var base=(c.teams&&c.teams.length&&c.teams.indexOf('all')<0)?(quTeamIds(c.teams).only||[]):(st.who&&st.who.only?st.who.only.slice():[]);ids.forEach(function(i){if(base.indexOf(i)<0)base.push(i)});st.who={only:base};st.rideLock=1;(c.notPeople?quPeopleIds(c.notPeople):[]).forEach(function(i){st.who=rideDrop(st.who,i)})}
function quMergeStep(d,s){var o={time:String(s.time||''),modal:MODAL[s.modal]?s.modal:'chegada',title:String(s.title||''),note:String(s.note||''),who:quTeamIds(s.teams)};
  var best=null,bl=0;d.steps.forEach(function(x){var l=quSame(x,o);if(l>bl){bl=l;best=x}});var hit=best;
  if(hit&&bl>=2){var moved=o.time&&o.time!==hit.time,old=hit.time;hit.time=o.time||hit.time;if(moved)quPropTime(d,hit,old);if(bl===3)hit.title=o.title||hit.title;if(o.note)quAddNote(hit,o.note,s.teams);if(s.teams&&s.teams.length&&bl===3)hit.who=o.who;quPeopleApply(hit,s);stamp(hit);if(moved)quPlace(d,hit);return}
  if(hit&&bl===1){var extra=Object.keys(quToks(o.title)).filter(function(w){return !{saida:1,onibus:1,van:1,voo:1,chegada:1,hotel:1,show:1}[w]&&!quToks(hit.title)[w]}).length;quAddNote(hit,(extra?o.title+(o.note?' ('+o.note+')':''):o.note),s.teams);stamp(hit);return}
  var keys=[],add=0,prev=-1;d.steps.forEach(function(x){var k=quMin(x.time);if(k==null)k=prev<0?0:prev;if(k+add<prev)add+=1440;keys.push(k+add);prev=k+add});
  var m=quMin(o.time),late=keys.some(function(k){return k>=720});if(m!=null&&m<360&&late&&keys.length&&keys[0]>=360)m+=1440;
  var pos=d.steps.length;if(m!=null)for(var i=0;i<keys.length;i++){if(keys[i]>m){pos=i;break}}
  o.id='s'+Date.now().toString(36)+Math.floor(Math.random()*999);quPeopleApply(o,s);stamp(o);d.steps.splice(pos,0,o);quVanAdd(d,o)}
function quApply(){
  var P=QU.plan,n=0;if(!P)return;
  (P.changes||[]).forEach(function(c){if(c._off)return;
    if(c.op==='notice'&&UNIF.test(c.text||''))return;
    if(c.op==='notice'){var sim=(S.notices||[]).filter(function(x){return quSim(x.text,c.text)>=0.55})[0];if(sim){if(quNorm(sim.text)!==quNorm(c.text)){sim.text=String(c.text).slice(0,300);if(c.level==='urg')sim.level='urg';stamp(sim);logH('Atualizou','Aviso: '+String(c.text).slice(0,80));n++}return}S.notices.unshift({id:'n'+Date.now().toString(36)+n,text:String(c.text).slice(0,300),level:c.level==='urg'?'urg':'info'});stamp(S.notices[0]);logH('Adicionou','Aviso: '+String(c.text).slice(0,80));n++;return}
    if(c.op==='step'){var fs=quFindStep(c),sd=fs&&fs.d,ss=fs&&fs.s;if(!ss)return;
      var mv=c.time&&/\d/.test(c.time)&&c.time!==ss.time,old0=ss.time;if(mv){ss.time=String(c.time);quPropTime(sd,ss,old0)}if(c.note)quAddNote(ss,c.note,c.teams);quPeopleApply(ss,c);stamp(ss);if(mv)quPlace(sd,ss);
      logH('Atualizou',sd.dd+'/'+sd.mm+' '+ss.time+' '+ss.title+(c.note?': '+String(c.note).slice(0,60):''),sd.dd+'/'+sd.mm);n++;return}
    if(c.op==='day'){var pr=String(c.date).split('/'),dd=('0'+pr[0]).slice(-2),mm=('0'+pr[1]).slice(-2);
      var d=S.days.filter(function(x){return x.dd===dd&&x.mm===mm})[0];
      if(!d){d={id:'d'+mm+dd,dd:dd,mm:mm,city:String(c.city||'Cidade n/i'),uf:String(c.uf||''),events:[],dayNotes:[],steps:[],flights:[],vans:[],vansNote:null,hotel:null,rooming:[],buses:[]};S.days.push(d);S.days.sort(function(a,b){return dkey(a)-dkey(b)})}
      if(c.city&&/n\/i/.test(d.city))d.city=String(c.city);
      if(c.steps&&c.steps.length)c.steps.forEach(function(s){quMergeStep(d,s)});
      if(c.show&&(c.show.name||c.show.showtime)){var ev=d.events.filter(function(e){return e.type==='show'})[0];if(!ev){ev={type:'show',name:'',venue:null,soundcheck:null,showtime:null,duration:null};d.events.push(ev)}['name','venue','showtime','soundcheck'].forEach(function(k){if(c.show[k])ev[k]=String(c.show[k])});if(c.show.showtime)quShowTime(d,String(c.show.showtime))}
      var ad=S.artists.days.filter(function(x){return x.dd===d.dd&&x.mm===d.mm})[0];
      if(c.hotel&&c.hotel.name){var hf=c.hotel.for||'equipe',mp=/^https:\/\//.test(String(c.hotel.maps||''))?String(c.hotel.maps):'';
        if(hf!=='artistico'){if(d.hotel&&d.hotel.name&&quNorm(d.hotel.name)!==quNorm(c.hotel.name))d.hotel=null;d.hotel=d.hotel||{name:'',address:'',phone:'',contact:'',checkin:'',checkout:'',distance:'',notes:[]};['name','address','phone','checkin','checkout','distance'].forEach(function(k){if(c.hotel[k])d.hotel[k]=String(c.hotel[k])});if(mp)d.hotel.maps=mp;stamp(d.hotel)}
        if(hf!=='equipe'&&ad){if(ad.hotel&&ad.hotel.name&&quNorm(ad.hotel.name)!==quNorm(c.hotel.name)&&!/consta|n\/i/i.test(ad.hotel.note||''))ad.hotel=null;ad.hotel=ad.hotel||{name:'',address:'',phone:'',contact:'',checkin:'',checkout:'',maps:null,note:''};['name','address','phone','checkin','checkout'].forEach(function(k){if(c.hotel[k])ad.hotel[k]=String(c.hotel[k])});if(mp)ad.hotel.maps=mp;if(/consta/i.test(ad.hotel.note||''))ad.hotel.note=''}}
      if(c.rooming&&c.rooming.rooms&&c.rooming.rooms.length){var rr=c.rooming.rooms.map(function(r){return {room:String(r.room||''),who:quRedact(r.who||''),type:String(r.type||'')}}).filter(function(r){return r.who});
        if(c.rooming.for==='artistico'){if(ad)ad.rooms=rr}else d.rooming=rr.map(function(r){return (r.room?r.room+': ':'')+r.who+(r.type?' · '+r.type:'')})}
      if(c.notes&&c.notes.length)d.dayNotes=c.notes.map(String).filter(function(n){return !UNIF.test(n)});
      if(c.bags&&c.bags.length){d.bags=d.bags||[];c.bags.forEach(function(t){t=String(t||'').trim();if(!t)return;var sm=d.bags.filter(function(x){return quSim(x.text,t)>=0.55})[0];if(sm){sm.text=t;stamp(sm)}else{var nb={id:uid('b'),text:t};stamp(nb);d.bags.push(nb)}})}
      logH('Atualizou',d.dd+'/'+d.mm+' '+d.city+' (pelo texto/PDF enviado)',d.dd+'/'+d.mm);n++}
  });
  var dup=quDedupeAll();
  S.updatedAt=new Date().toISOString();ui.dirty=true;QU.plan=null;QU.text='';QU.file=null;QU.msg=n+' mudança(s) aplicada(s) e publicada(s) para todos.'+(dup?' '+dup+' item(ns) repetido(s) juntado(s).':'');render();if(n||dup)publish();
}
app.addEventListener('click',function(e){var t=e.target.closest('[data-qu]');if(!t||!isAdmin())return;var a=t.dataset.qu;
  if(a==='dedupe'){var k=quDedupeAll();QU.msg=k?k+' item(ns) repetido(s) juntado(s) e publicado(s) para todos.':'Nenhum horário repetido encontrado.';render();if(k)publish();return}
  if(a==='go')quRun();else if(a==='cancel'){QU.plan=null;render()}else if(a==='apply')quApply()});
app.addEventListener('input',function(e){if(e.target.id==='qu-text')QU.text=e.target.value});
