/* ---------- ônibus: paradas e troca de motoristas ---------- */
function hav(a,b){var R=6371,t=Math.PI/180,dl=(b[0]-a[0])*t,dn=(b[1]-a[1])*t,x=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a[0]*t)*Math.cos(b[0]*t)*Math.sin(dn/2)*Math.sin(dn/2);return 2*R*Math.asin(Math.sqrt(x))}
function durMin(t){var m=String(t||'').match(/(\d+)\s*h\s*(\d{1,2})?/i);return m?(+m[1])*60+(+(m[2]||0)):null}
function stopPlan(x){var A=cityLL(x.from),B=cityLL(x.to);if(!A||!B)return '';
  var stops=x.stops||[];var pts=[{n:x.from.split(',')[0],ll:A.ll}];stops.forEach(function(st){var c=cityLL(st);if(c)pts.push({n:st,ll:c.ll})});pts.push({n:x.to.split(',')[0],ll:B.ll});
  var seg=[],tot=0;for(var i=1;i<pts.length;i++){var dd=hav(pts[i-1].ll,pts[i].ll);seg.push(dd);tot+=dd}
  var km=parseFloat(String(x.dist||'').replace(/\./g,'').replace(',','.'))||tot*1.25,mins=durMin(x.dur)||Math.round(km/70*60);
  var h='<div class="vt"><div class="lb">'+icon('onibus')+'Paradas e troca de motoristas</div><div class="card-n">Referência: pausa de 30 min a cada 4h ao volante no transporte de passageiros (CTB, art. 67-C). Confirme com a empresa do ônibus.</div>';
  if(stops.length) h+='<div class="card-n" style="margin-top:6px"><b style="color:var(--ink)">Paradas combinadas:</b> '+esc(stops.join(' · '))+'</div>';
  if(mins<=240){return h+'<div class="card-n" style="margin-top:6px">Trecho de '+Math.floor(mins/60)+'h'+('0'+mins%60).slice(-2)+': cabe sem troca obrigatória.</div></div>'}
  var list=[];for(var t=240;t<mins-20;t+=240){var fr=t/mins,target=fr*tot,acc=0,ll=pts[pts.length-1].ll;
    for(var j=0;j<seg.length;j++){if(acc+seg[j]>=target){var u=(target-acc)/seg[j];ll=[pts[j].ll[0]+(pts[j+1].ll[0]-pts[j].ll[0])*u,pts[j].ll[1]+(pts[j+1].ll[1]-pts[j].ll[1])*u];break}acc+=seg[j]}
    var near=null,nd=1e9;Object.keys(CITYLL).forEach(function(k){var q=hav(ll,CITYLL[k]);if(q<nd){nd=q;near=k}});
    list.push('<div class="car"><span><b>~'+Math.floor(t/60)+'h de estrada</b> · km '+Math.round(km*fr)+(nd<45?' · perto de '+esc(near.replace(/\b\w/g,function(c){return c.toUpperCase()})):'')+'<br><span class="card-n">Troca de motorista + 30 min</span></span><a href="https://www.google.com/maps/search/posto+24h/@'+ll[0].toFixed(4)+','+ll[1].toFixed(4)+',11z" target="_blank" rel="noopener">Postos</a></div>')}
  return h+'<div class="card-n" style="margin-top:6px">'+Math.round(km)+' km · '+Math.floor(mins/60)+'h'+('0'+mins%60).slice(-2)+' de estrada → '+list.length+' parada(s) sugerida(s):</div>'+list.join('')+'<div class="card-n">Pontos estimados no traçado. Use o botão "Postos" para achar um posto 24h seguro perto de cada ponto.</div></div>'}
